<?= $this->section('main-content') ?>
<main class="container-fluid py-4" id="shopify-order-mappings">
    <div class="d-flex justify-content-between align-items-center mb-4"><div><p class="text-uppercase text-muted small mb-1">Shopify · Order Operations</p><h1 class="h4 mb-1">Product / variant medicine mappings</h1><p class="text-muted mb-0">Shopify prices are never used as ROOTINS medicine prices.</p></div><a class="btn btn-outline-secondary" href="<?= base_url('admin/integrations/shopify/order-operations') ?>">Order queue</a></div>
    <div class="card shadow-sm mb-4"><div class="card-body"><form class="form-row"><div class="col-md-2"><input class="form-control" name="product" placeholder="Product" value="<?= esc($filters['product'] ?? '') ?>"></div><div class="col-md-2"><input class="form-control" name="variant" placeholder="Variant" value="<?= esc($filters['variant'] ?? '') ?>"></div><div class="col-md-2"><input class="form-control" name="sku" placeholder="SKU" value="<?= esc($filters['sku'] ?? '') ?>"></div><div class="col-md-2"><input class="form-control" name="medicine" placeholder="ROOTINS medicine" value="<?= esc($filters['medicine'] ?? '') ?>"></div><div class="col-md-2"><select class="form-control" name="status"><option value="">All statuses</option><option value="active" <?= ($filters['status'] ?? '') === 'active' ? 'selected' : '' ?>>Active</option><option value="inactive" <?= ($filters['status'] ?? '') === 'inactive' ? 'selected' : '' ?>>Inactive</option></select></div><div class="col-md-2"><button class="btn btn-primary mr-2" type="submit">Filter</button><a class="btn btn-light" href="<?= base_url('admin/integrations/shopify/order-mappings') ?>">Reset</a></div></form></div></div>
    <div class="card shadow-sm mb-4"><div class="card-header bg-white"><h2 class="h6 mb-0">Add or edit mapping</h2></div><div class="card-body"><form class="row" method="post" action="<?= base_url('admin/integrations/shopify/order-mappings/save') ?>" data-shopify-operation-form><?= csrf_field() ?><input type="hidden" name="id" value=""><div class="col-md-2"><input class="form-control" name="shopify_product_id" placeholder="Shopify product ID" required></div><div class="col-md-2"><input class="form-control" name="shopify_variant_id" placeholder="Shopify variant ID" required></div><div class="col-md-2"><input class="form-control" name="shopify_product_title" placeholder="Product title"></div><div class="col-md-2"><input class="form-control" name="shopify_variant_title" placeholder="Variant title"></div><div class="col-md-2"><input class="form-control" name="shopify_sku" placeholder="SKU"></div><div class="col-md-2"><select class="form-control" name="medicine_id" required><option value="">ROOTINS medicine</option><?php foreach ($medicines as $medicine): ?><option value="<?= (int) $medicine['id'] ?>"><?= esc($medicine['medicine_name'] . (($medicine['strength'] ?? '') !== '' ? ' · ' . $medicine['strength'] : '') . (($medicine['unit'] ?? '') !== '' ? ' / ' . $medicine['unit'] : '')) ?></option><?php endforeach; ?></select></div><div class="col-12 mt-3"><button class="btn btn-primary" type="submit">Save mapping</button><a class="btn btn-outline-secondary ml-2" href="<?= base_url('admin/integrations/shopify/order-mappings') ?>">Clear</a></div></form></div></div>
    <div class="d-flex justify-content-between align-items-center mb-2"><h2 class="h6 mb-0">Mappings</h2><a href="<?= base_url('admin/integrations/shopify/order-operations?status=pending_mapping') ?>" class="badge badge-warning">Unmapped orders → queue</a></div>
    <div class="card shadow-sm"><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Product</th><th>Product ID</th><th>Variant</th><th>Variant ID</th><th>SKU</th><th>ROOTINS medicine</th><th>Strength/unit</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><?php if ($mappings === []): ?><tr><td colspan="10" class="text-center text-muted py-4">No mappings found.</td></tr><?php endif; ?><?php foreach ($mappings as $mapping): ?><tr><td><?= esc($mapping['shopify_product_title'] ?? '—') ?></td><td><code><?= esc($mapping['shopify_product_id']) ?></code></td><td><?= esc($mapping['shopify_variant_title'] ?? '—') ?></td><td><code><?= esc($mapping['shopify_variant_id'] ?? '—') ?></code></td><td><?= esc($mapping['shopify_sku'] ?? '—') ?></td><td><?= esc($mapping['medicine_name'] ?? 'Missing') ?></td><td><?= esc(trim((string) (($mapping['strength'] ?? '') . ' ' . ($mapping['unit'] ?? ''))) ?: '—') ?></td><td><span class="badge badge-<?= ($mapping['status'] ?? '') === 'active' ? 'success' : 'secondary' ?>"><?= esc(ucfirst($mapping['status'])) ?></span></td><td><?= esc($mapping['updated_at'] ?? '') ?></td><td><button class="btn btn-sm btn-outline-primary shopify-mapping-edit" type="button" data-mapping='<?= esc(json_encode($mapping), 'attr') ?>'>Edit</button><form class="d-inline" method="post" action="<?= base_url('admin/integrations/shopify/order-mappings/toggle/' . (int) $mapping['id']) ?>" data-shopify-operation-form><?= csrf_field() ?><button class="btn btn-sm btn-outline-secondary" type="submit"><?= ($mapping['status'] ?? '') === 'active' ? 'Deactivate' : 'Activate' ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
</main>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><script>document.querySelectorAll('.shopify-mapping-edit').forEach(function(button){button.addEventListener('click',function(){var data=JSON.parse(button.dataset.mapping),form=document.querySelector('[data-shopify-operation-form]');Object.keys(data).forEach(function(key){var field=form.querySelector('[name="'+key+'"]');if(field)field.value=data[key]||'';});window.scrollTo({top:0,behavior:'smooth'});});});document.querySelectorAll('[data-shopify-operation-form]').forEach(function(form){form.addEventListener('submit',function(e){e.preventDefault();fetch(form.action,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest'},body:new FormData(form)}).then(function(r){return r.json();}).then(function(d){alert(d.msg||'Saved.');if(d.status)location.reload();});});});</script><?= $this->endSection() ?>
